// Literal - forma mais comum e mais legível
const regexLiteral = /gato/i;

// Construtor - útil quando o padrão vem de uma variável
const termo = "gato";
const regexDinamico = new RegExp(termo, "i");

console.log(regexLiteral.test("Tenho um Gato"));  // true
console.log(regexDinamico.test("Tenho um Gato")); // true

// Numa string usada no construtor, a barra invertida duplica-se
const comBarra = new RegExp("\\d+"); // equivalente a /\d+/
console.log(comBarra.test("Ano 2026")); // true

const texto = `Primeira linha
Segunda LINHA
Terceira linha`;

console.log(/^linha/i.test("LINHA de teste"));  // true (i: ignora maiúsculas)
console.log(texto.match(/^segunda.*$/im)[0]);   // "Segunda LINHA" (m: ^ $ por linha)

const comQuebra = "início\nfim";
console.log(/início.fim/.test(comQuebra));  // false: '.' não apanha \n
console.log(/início.fim/s.test(comQuebra)); // true: com 's', '.' apanha \n

const repetido = "gato gato gato";
console.log(repetido.match(/gato/g)); // ["gato", "gato", "gato"]

const texto = "Sala 101, telefone 912-345-678";

console.log(texto.match(/\d+/g));      // ["101", "912", "345", "678"]
console.log(texto.match(/[aeiou]/gi)); // todas as vogais, maiúsculas e minúsculas

const identificador = /^[a-zA-Z_][a-zA-Z0-9_]*$/;
console.log(identificador.test("nomeVariavel_2")); // true
console.log(identificador.test("2nomeInvalido"));  // false

const semDigitos = /[^0-9]+/g;
