// Com a flag 'g', exec() avança lastIndex a cada chamada
const regexPalavras = /\b\w{4,}\b/g;
const frase = "O rato roeu a rolha da garrafa";
let m;
while ((m = regexPalavras.exec(frase)) !== null) {
  console.log(`"${m[0]}" na posição ${m.index}`);
}

const texto = "O ano de 2024 e o ano de 2026";

console.log(texto.match(/\d{4}/));   // ["2024", index: 9, ...] (sem 'g': só a 1ª ocorrência)
console.log(texto.match(/\d{4}/g));  // ["2024", "2026"] (com 'g': todas)

for (const m of texto.matchAll(/\d{4}/g)) {
  console.log(m[0], "na posição", m.index);
}

console.log(texto.replace(/\d{4}/, "20XX"));  // só troca a primeira ocorrência
console.log(texto.replace(/\d{4}/g, "20XX")); // troca todas

const comColchetes = texto.replace(/\d{4}/g, (ano) => `[${ano}]`);
console.log(comColchetes); // "O ano de [2024] e o ano de [2026]"

console.log("um,dois;três  quatro".split(/[,;\s]+/));
// ["um", "dois", "três", "quatro"]

