function extrairHashtags(texto) {
  const encontrados = texto.match(/#\w+/g);
  if (!encontrados) return [];
  return encontrados.map((hashtag) => hashtag.slice(1));
}

console.log(extrairHashtags("Adorei o #curso de #JavaScript hoje!"));
// ["curso", "JavaScript"]
console.log(extrairHashtags("Sem hashtags aqui"));
// []

function mascararTelefones(texto) {
  return texto.replace(/\d{9}/g, (numero) => {
    const visiveis = numero.slice(-4);
    const escondidos = "*".repeat(numero.length - 4);
    return escondidos + visiveis;
  });
}

console.log(mascararTelefones("Ligar para 912345678 ou 934567890"));
// "Ligar para *****5678 ou *****7890"
console.log(mascararTelefones("Sem números aqui"));
// "Sem números aqui"

function contarPalavras(texto) {
  const contagem = new Map();
  const palavras = texto.toLowerCase().matchAll(/[a-z]+/g);

  for (const [palavra] of palavras) {
    contagem.set(palavra, (contagem.get(palavra) ?? 0) + 1);
  }

  return contagem;
}

const resultado = contarPalavras("O rato roeu a rolha. A rolha era do rato!");
console.log(resultado);
// Map(7) { 'o' => 1, 'rato' => 2, 'roeu' => 1, 'a' => 2, 'rolha' => 2, 'era' => 1, 'do' => 1 }
